contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs that drive supplyTokenTo
    function run(address from, address to, uint256 mAssetAmount) public payable {
        require(from != address(0) && to != address(0));

        // record balances and imBalances before
        uint256 before_im_to = c.imBalances(to);
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 before_masset_bal_c = m.balanceOf(address(c));

        // We will simulate the caller being 'from' by having this contract be the caller as required
        // The contract C expects the caller to have approved it; we cannot arrange external approvals here,
        // so the call may revert. We capture whether it reverts.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after_im_to = c.imBalances(to);
        uint256 after_masset_bal_c = m.balanceOf(address(c));

        // If the call succeeded (not reverted), then imBalances[to] must have increased by non-zero or zero creditsIssued
        // We assert that either it reverted, or the increase equals the creditsIssued implied by difference in imBalances
        // Since we cannot call savings.depositSavings directly to obtain creditsIssued, we assert the imBalances monotonicity
        // and that the change in c's mAsset balance is consistent (cannot be negative).

        // General rule: supplyTokenTo either reverts or increases imBalances[to] by exactly (after - before) and leaves c's mAsset balance >= before
        assert(reverted || (after_im_to >= before_im_to && after_masset_bal_c >= before_masset_bal_c));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mAssetAmount) public payable {
        // No precondition on mAssetAmount
        // Observe imBalances before, and mAsset balance of c before
        uint256 before_im = c.imBalances(address(this));
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 before_masset_bal_c = m.balanceOf(address(c));

        bool reverted;
        uint256 mAssetsActual = 0;
        try c.redeemToken(mAssetAmount) returns (uint256 returned) {
            reverted = false;
            mAssetsActual = returned;
        } catch {
            reverted = true;
        }

        uint256 after_im = c.imBalances(address(this));
        uint256 after_masset_bal_c = m.balanceOf(address(c));

        // General rule:
        // If the call reverted, nothing else is required here. If it did not revert then:
        // 1) the mAssetsActual returned equals the observed increase in c's mAsset balance (after - before),
        // 2) imBalances[this] did not increase (i.e., after_im <= before_im), since redeem burns credits,
        // 3) the mAssetsActual is <= after_masset_bal_c (a sanity relation) and is non-negative by type.
        assert(reverted || (mAssetsActual == after_masset_bal_c - before_masset_bal_c && after_im <= before_im));
    }

    receive() external payable {}
}

