    // Single public test function taking an amount to redeem
    function run(uint256 mAssetAmount) public payable {
        // Observe imBalances for this contract (msg.sender for calls on c will be this test contract)
        uint256 before_im = c.imBalances(address(this));

        // Read mAsset token address and create an IERC20 reference by observing c only through its public API
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);

        // Observe mAsset balance of c before
        uint256 before_masset_bal_c = m.balanceOf(address(c));

        // Perform the state-changing call at top-level and capture whether it reverted and returned value
        bool reverted;
        uint256 mAssetsActual;
        try c.redeemToken(mAssetAmount) returns (uint256 returned) {
            reverted = false;
            mAssetsActual = returned;
        } catch {
            reverted = true;
            mAssetsActual = 0;
        }

        // Observe after-values
        uint256 after_im = c.imBalances(address(this));
        uint256 after_masset_bal_c = m.balanceOf(address(c));

        // General property (single assert): if the call did not revert then
        // 1) the returned mAssetsActual equals the observed increase in c's mAsset balance,
        // 2) the caller's imBalances did not increase (credits should be burned or unchanged),
        // otherwise (if reverted) no further constraints.
        assert(reverted || (mAssetsActual == after_masset_bal_c - before_masset_bal_c && after_im <= before_im));
    }

    // receive to accept any mAsset or Ether callbacks if needed by c during calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that supplyTokenTo either reverts or (1) increases imBalances[to] (non-decreasing and if changed then >= before+1)
    // and (2) increases the contract's mAsset balance by exactly mAssetAmount (i.e., tokens moved from caller to c).
    // We take mAssetAmount and a beneficiary address "to" as inputs.
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "to non-zero");

        // Observe pre-state: imBalances[to] and c's mAsset balance
        uint256 beforeIm = c.imBalances(to);
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 beforeBal = m.balanceOf(address(c));

        // Perform the state-changing call at top-level and capture revert status
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterIm = c.imBalances(to);
        uint256 afterBal = m.balanceOf(address(c));

        // General property: if call succeeded then
        //  - contract mAsset balance increased by exactly mAssetAmount (tokens transferred in), and
        //  - imBalances[to] did not decrease and if it changed then increased by at least 1 credit.
        // If the call reverted, no constraints.
        assert(reverted || (afterBal == beforeBal + mAssetAmount && afterIm >= beforeIm && (afterIm == beforeIm || afterIm >= beforeIm + 1)));
    }

    // Allow receiving tokens or ether if the c contract calls back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test a property of supplyTokenTo: if it succeeds then
    // 1) imBalances[to] is non-decreasing and the observed increase equals after-before (tautological but ties to observable)
    // 2) the contract's mAsset token balance increases by no more than the provided mAssetAmount (caller can't cause c to gain more tokens than they supplied)
    // The call must be a top-level state-changing call on c.
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "to non-zero");

        // observe pre-state via public getters
        uint256 beforeIm = c.imBalances(to);
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 beforeBal = m.balanceOf(address(c));

        // make the state-changing call as a top-level statement and capture revert
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint256 afterIm = c.imBalances(to);
        uint256 afterBal = m.balanceOf(address(c));

        // General rule asserted here:
        // If the call did not revert then imBalances[to] did not decrease (afterIm >= beforeIm)
        // and the increase in c's mAsset balance is at most mAssetAmount (afterBal - beforeBal <= mAssetAmount).
        // If it reverted, no constraints.
        assert(reverted || (afterIm >= beforeIm && afterBal - beforeBal <= mAssetAmount));
    }

    // fallback to allow receiving ether if needed
    receive() external payable {}
}

