        // General rule: if call succeeded, afterCredits >= beforeCredits
        // and increase equals the credits that savings.depositSavings would have returned.
        // We cannot call savings.depositSavings directly here, but we can assert monotonicity
        // and that if no revert then afterCredits > beforeCredits only when mAssetAmount>0.
        // Single assert as required:
        assert(
            // If reverted, no observable increase (could be anything) is allowed; but we must ensure
            // that if it did NOT revert then credits did not decrease and behave sensibly wrt input
            (reverted) || (
                afterCredits >= beforeCredits &&
                // if positive input, expect a strictly non-zero increase (creditsIssued > 0)
                (mAssetAmount == 0 || afterCredits > beforeCredits)
            )
        );
    }

