contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will drive c.supplyTokenTo(amount, to). We must hold mAsset tokens and approve c to pull them.
    // Inputs: amount of mAsset to supply, beneficiary address to credit, and an approval amount flag.
    // The test assumes the mAsset token used by c implements IERC20 interface and is accessible via c.depositToken().
    function run(uint256 amount, address to, uint256 approveAmount) public payable {
        require(to != address(0), "beneficiary nonzero");

        IERC20 token = IERC20(c.depositToken());

        // Ensure this contract has at least `amount` tokens. If not, the subsequent transferFrom will revert
        // so we want to check behavior only when we have tokens and approved allowance.
        // We cannot mint tokens here; instead we require that this contract already has balance >= amount.
        require(token.balanceOf(address(this)) >= amount, "insufficient test token balance");

        // Approve c to pull tokens. Use provided approveAmount to allow testing approve zero/nonzero scenarios.
        token.approve(address(c), approveAmount);

        // Read pre-state: exchange rate and beneficiary underlying balance as reported by c
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 underlyingBefore = c.balanceOfToken(to);

        // Read imBalances via observable: we cannot read imBalances directly (it's public mapping named imBalances),
        // but there is no getter for that mapping in the interface; however balanceOfToken depends on imBalances and exchangeRate.
        // Call supplyTokenTo; capture whether it reverts.
        bool reverted;
        try c.supplyTokenTo(amount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 underlyingAfter = c.balanceOfToken(to);

        // General rule (assert): If the call did not revert, then underlyingAfter is >= underlyingBefore.
        // Furthermore, the increase in underlying reported must be at least the expected mAsset-equivalent
        // computed using the exchange rate at the time of call (we conservatively use rateAfter to avoid underflow),
        // unless exchange rate decreased dramatically; so we assert monotonicity of reported underlying on non-revert.
        // Also if it reverted, then nothing observable must have changed: require underlyingAfter == underlyingBefore.
        assert((!reverted && underlyingAfter >= underlyingBefore) || (reverted && underlyingAfter == underlyingBefore));
    }

    receive() external payable {}
}

