contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check for redeemToken
    function run(uint256 amount) public payable {
        // Observe deposit token via c's public view
        address depositToken = c.depositToken();
        IERC20 token = IERC20(depositToken);

        // Read this contract's mAsset balance before calling redeemToken
        uint256 balBefore = token.balanceOf(address(this));

        // Make the state-changing call to c as a top-level statement and capture revert status and return value
        bool reverted;
        uint256 returned;
        try c.redeemToken(amount) returns (uint256 r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = 0;
        }

        // Read this contract's mAsset balance after the call
        uint256 balAfter = token.balanceOf(address(this));

        // General property:
        // If the call reverted, this contract's mAsset balance is unchanged.
        // If the call succeeded, the increase in this contract's mAsset balance equals the returned value (and is >= 0).
        assert((reverted && balAfter == balBefore) || (!reverted && balAfter == balBefore + returned));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking amount and expecting behavior for redeemToken
    function run(uint256 redeemAmount) public payable {
        // Precondition: we will try to call redeemToken; no other preconditions.
        require(true);

        // We will impersonate an external user by first supplying some tokens to c from this contract.
        // Step 1: read exchange rate and this contract's balanceOfToken before any operations
        uint256 beforeExchange = c.savings().exchangeRate();
        // read imBalances-backed observable: balanceOfToken for this contract
        uint256 beforeUnderlying = c.balanceOfToken(address(this));

        // To be able to redeem, we first supply tokens if redeemAmount > 0: call supplyTokenTo
        // We cannot mint ERC20 tokens here; but we conservatively attempt to call redeemToken and observe revert or success.
        bool reverted;
        uint256 mAssetBalanceBefore = c.mAsset().balanceOf(address(c));
        uint256 thisBalanceBefore = c.mAsset().balanceOf(address(this));

        // Try redeem; catch revert flag
        uint256 mAssetsActual = 0;
        try c.redeemToken(redeemAmount) returns (uint256 returned) {
            reverted = false;
            mAssetsActual = returned;
        } catch {
            reverted = true;
        }

        uint256 mAssetBalanceAfter = c.mAsset().balanceOf(address(c));
        uint256 thisBalanceAfter = c.mAsset().balanceOf(address(this));
        uint256 beforeImUnderlying = beforeUnderlying;
        uint256 afterImUnderlying = c.balanceOfToken(address(this));

        // General rule asserted: if redeemToken did not revert, then
        // 1) the caller's mAsset received equals the increase of this contract's mAsset balance (thisBalanceAfter - thisBalanceBefore),
        //    and equals mAssetsActual returned by the call;
        // 2) c's mAsset balance change equals negative of that transfer (i.e., c lost that amount);
        // 3) the observable underlying balanceOfToken of the caller did not increase (it should be decreased or equal) because credits were burned.
        // We express these as an assertion combining these relations. For reverts we assert nothing about amounts except that reverted==true implies returned values are zero.

        assert(
            reverted || (
                // returned amount equals this contract's mAsset gain
                mAssetsActual == (thisBalanceAfter - thisBalanceBefore)
                // c's mAsset balance decreased by same amount
                && (mAssetBalanceBefore - mAssetBalanceAfter) == mAssetsActual
                // the observable underlying (balanceOfToken) did not increase compared to before
                && afterImUnderlying <= beforeImUnderlying
            )
        );
    }

    // allow receiving tokens if target contract sends ETH (not used but present)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(uint256 redeemAmount) public payable {
        require(true);

        // Observe balances before the call
        uint256 cBalanceBefore = c.mAsset().balanceOf(address(c));
        uint256 callerBalanceBefore = c.mAsset().balanceOf(address(this));

        bool reverted;
        uint256 returnedAmount = 0;

        // Make the state-changing call at top-level and capture revert using try/catch
        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            reverted = false;
            returnedAmount = mAssetsActual;
        } catch {
            reverted = true;
        }

        // Observe balances after the call
        uint256 cBalanceAfter = c.mAsset().balanceOf(address(c));
        uint256 callerBalanceAfter = c.mAsset().balanceOf(address(this));

        uint256 callerReceived = callerBalanceAfter >= callerBalanceBefore ? callerBalanceAfter - callerBalanceBefore : 0;
        uint256 cDelta = cBalanceBefore >= cBalanceAfter ? cBalanceBefore - cBalanceAfter : 0;

        // General rule: if call did not revert then the returned amount equals what the caller received
        // and c's mAsset balance decreased by at least that returned/received amount.
        assert(reverted || (returnedAmount == callerReceived && cDelta >= returnedAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(uint256 redeemAmount) public payable {
        require(true);

        // Observe caller's reported underlying balance and exchange rate before
        uint256 exchBefore = c.savings().exchangeRate();
        uint256 underlyingBefore = c.balanceOfToken(address(this)); // in underlying (mAssets)

        bool reverted;
        uint256 returnedAmount;

        // Top-level state-changing call, capture revert with try/catch
        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            reverted = false;
            returnedAmount = mAssetsActual;
        } catch {
            reverted = true;
            returnedAmount = 0;
        }

        // Observe after values
        uint256 exchAfter = c.savings().exchangeRate();
        uint256 underlyingAfter = c.balanceOfToken(address(this));

        // Compute observed change in underlying (no underflow in assert: use comparisons)
        uint256 underlyingDecreased = underlyingBefore >= underlyingAfter ? underlyingBefore - underlyingAfter : 0;

        // If call succeeded (did not revert) then:
        // - the returnedAmount equals the actual mAsset tokens received by the caller (observable as increase in this contract's mAsset balance)
        //   We approximate this by checking that underlying decrease (credits burned converted at exchange rate before) is at least the returnedAmount when converted to underlying using exchBefore.
        // - imBalances (reflected in balanceOfToken) decreases by at least the underlying equivalent of returnedAmount
        // Because exchangeRate may change during call, require that if not reverted, exchBefore equals exchAfter to avoid ambiguity.

        assert(reverted || (exchBefore == exchAfter && underlyingDecreased * 1e18 >= returnedAmount * 1e18 && returnedAmount > 0));
    }

    receive() external payable {}
}

