contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry that performs the property check
    function run(address from, address to, uint256 mAssetAmount) public payable {
        require(from != address(0) && to != address(0), "nonzero addrs");

        // observe exchange rate before
        uint256 rateBefore = c.savings().exchangeRate();

        // observe balances-of-token (which uses imBalances * exchangeRate / 1e18)
        uint256 toBefore = c.balanceOfToken(to);
        uint256 fromBefore = c.balanceOfToken(from);

        // Try to call supplyTokenTo; it may revert if transferFrom or depositSavings fails.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe exchange rate and balances after (even if reverted, calls are still allowed views)
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 toAfter = c.balanceOfToken(to);
        uint256 fromAfter = c.balanceOfToken(from);

        // General rule:
        // If the call succeeded (not reverted) then:
        //  - the recipient's balanceOfToken should be >= toBefore (it must not decrease)
        //  - the caller's balanceOfToken should be >= fromBefore (imBalances for caller should not decrease due to supplying to someone else)
        //  - the increase in recipient's balance, measured in token-units, should be at least the nominal mAssetAmount scaled by the exchangeRate at the time of observation divided by 1e18.
        // We use rateAfter for the scaling (both rates are external observable), and avoid underflow by using comparisons.

        assert(
            reverted || (
                toAfter >= toBefore
                && fromAfter >= fromBefore
                && (toAfter - toBefore) * 1e18 >= mAssetAmount * rateAfter
            )
        );
    }

    // accept ETH if needed by any calls
    receive() external payable {}
}

