contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising supplyTokenTo then redeemToken and asserting a general invariant
    // params:
    // from: address that will be used as msg.sender for token transfer simulation cannot be changed here,
    // but we drive only c from this contract (which is msg.sender to c). To obey constraints we use this contract
    // as actor for supply and redeem. We take amounts as inputs.
    function run(uint256 supplyAmount, uint256 redeemRequest) public payable {
        require(true);

        // Observe pre-state: exchange rate and this contract's view of balanceOfToken
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balTokenBefore = c.balanceOfToken(address(this));
        uint256 contractMAssetBefore = c.mAsset().balanceOf(address(c));
        uint256 myMAssetBefore = c.mAsset().balanceOf(address(this));

        // We cannot actually transfer ERC20 tokens from arbitrary addresses in this harness since
        // we don't mint tokens here; but we can still call the functions to check logical behavior
        // using try/catch to record reverts. Call supplyTokenTo and redeemToken and record reverts.
        bool supplyReverted;
        try c.supplyTokenTo(supplyAmount, address(this)) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // Observe post-supply state
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balTokenAfter = c.balanceOfToken(address(this));
        uint256 contractMAssetMid = c.mAsset().balanceOf(address(c));

        bool redeemReverted;
        try c.redeemToken(redeemRequest) returns (uint256 actual) {
            redeemReverted = false;
        } catch {
            redeemReverted = true;
        }

        // final observations
        uint256 balTokenFinal = c.balanceOfToken(address(this));
        uint256 contractMAssetFinal = c.mAsset().balanceOf(address(c));
        uint256 myMAssetFinal = c.mAsset().balanceOf(address(this));

        // General rule asserted:
        // If supply succeeded then the recipient's reported balanceOfToken (in mAssets) should not be less than before,
        // i.e., supply cannot decrease the token-denominated balance. Also, if redeem succeeded then the contract's
        // mAsset balance must have decreased by exactly the amount of mAssets transferred out to this contract
        // (observed as myMAssetFinal - myMAssetBefore), and the user's balanceOfToken must not have increased due to redeem.
        assert(
            // supply non-decreasing effect on balanceOfToken when supply didn't revert
            (supplyReverted || balTokenAfter >= balTokenBefore)
            &&
            // redeem non-increasing effect on balanceOfToken when redeem didn't revert
            (redeemReverted || balTokenFinal <= balTokenAfter)
            &&
            // if redeem didn't revert then contract's balance decreased by the tokens that appeared in this contract
            (redeemReverted || (contractMAssetMid - contractMAssetFinal == myMAssetFinal - myMAssetMid()))
        );
    }

    // helper read function to get this contract's mAsset balance mid-call without using extra functions on c
    function myMAssetMid() internal view returns (uint256) {
        return c.mAsset().balanceOf(address(this));
    }

    // receive to allow any token-less Ether transfers if needed by c
    receive() external payable {}
}

