    // single public entrypoint for the property-based test
    // params:
    // - mAssetAmount: amount to supply
    // - to: beneficiary address to credit
    // - sponsor: an address that will be the msg.sender for safeTransferFrom simulation (not possible here),
    //   but we rely only on observable imBalances change after supplyTokenTo; msg.sender in calls from this contract
    //   will be InvMutTest itself.
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0));

        // Read imBalances for beneficiary before the call via public getter
        uint256 before = c.imBalances(to);

        // Attempt the state-changing call and capture whether it reverted.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read imBalances after the call
        uint256 after = c.imBalances(to);

        // General rule:
        // If the call did not revert, then after >= before (no decrease), and the increment (after - before)
        // equals the value returned by savings.depositSavings when called with mAssetAmount — however we cannot
        // call savings.depositSavings directly here. But C's supplyTokenTo calls savings.depositSavings and
        // then increments imBalances by creditsIssued. Thus we assert a monotonic increase: after >= before.
        // Additionally, when not reverted, the change must be consistent with exchangeRate() view through
        // balanceOfToken: the balanceOfToken(to) after should be >= (before * exchangeRate)/1e18 and
        // equals (after * exchangeRate)/1e18; we express a conservative invariant: non-reverting supply does not
        // decrease the beneficiary's token-equivalent balance and increases it by at most a value proportional
        // to mAssetAmount (we require at least non-decrease). This avoids calling internal savings.

        // Assert the general rule: if supplyTokenTo succeeded, imBalances[to] did not decrease.
        assert(reverted || after >= before);
    }

    receive() external payable {}
}

