            redeemReverted = true;
        }

        // Read exchange rate and balance after operations
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 afterTokenBalance = c.balanceOfToken(recipient);

        // General rule: If both operations succeeded (non-reentrant and proper transfers), then
        // the recipient's observed mAsset-equivalent balance (balanceOfToken) should not be greater after
        // these operations than before. This enforces that redeeming cannot increase the recipient's credited underlying.
        // We express: if neither call reverted then afterTokenBalance <= beforeTokenBalance, otherwise no requirement.
        assert( supplyReverted || redeemReverted || afterTokenBalance <= beforeTokenBalance );
    }

