        }

        // Read after values
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balanceTokenAfter = c.balanceOfToken(beneficiary);

        // General rule: if supplyTokenTo succeeded, then the beneficiary's balanceOfToken measured
        // after must be at least as large as before when compared using the same exchange rate snapshot.
        // To avoid mixing different exchange rates, require that the exchange rate did not decrease
        // between the snapshots; if it did decrease we conservatively skip the check (no requirement).
        // Thus: if supply succeeded AND rateAfter >= rateBefore then balanceTokenAfter >= balanceTokenBefore.
        assert(supplyReverted || rateAfter < rateBefore || balanceTokenAfter >= balanceTokenBefore);
    }

