contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a supplyAmount and a beneficiary. This contract (the harness) is the msg.sender
    // for calls into c. The harness must be set up externally with any required token approvals/balances.
    function run(uint256 supplyAmount, address beneficiary) public payable {
        require(beneficiary != address(0), "beneficiary nonzero");

        // Observe before: snapshot the savings exchange rate and the beneficiary's balanceOfToken
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balanceBefore = c.balanceOfToken(beneficiary);

        // Attempt the state-changing call as a top-level statement and capture whether it reverted.
        bool supplyReverted;
        try c.supplyTokenTo(supplyAmount, beneficiary) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // Observe after using the same kind of public reads
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balanceAfter = c.balanceOfToken(beneficiary);

        // General rule: If supply succeeded, then using the AFTER exchange rate snapshot the
        // beneficiary's balanceOfToken (which already returns mAssets scaled by the current
        // exchange rate) must be at least as large as before when both are interpreted under
        // the same exchange rate (rateAfter). To be conservative: if supply succeeded, require
        // that balanceAfter >= balanceBefore * rateAfter / rateBefore when rateBefore>0.
        // Avoid division by zero: if rateBefore == 0 then we only assert when supply reverted.

        if (supplyReverted) {
            assert(supplyReverted == true);
        } else {
            if (rateBefore == 0) {
                // If prior rate was zero, we cannot compare ratios safely; just require non-revert
                assert(supplyReverted == false);
            } else {
                // Multiply to avoid fractional comparisons: balanceAfter * rateBefore >= balanceBefore * rateAfter
                // Both sides are uint256; this expresses that beneficiary's value did not decrease
                assert(balanceAfter * rateBefore >= balanceBefore * rateAfter);
            }
        }
    }

    receive() external payable {}
}

