        uint256 before = c.balanceOfToken(to);

        // Attempt to supply: this call transfers mAsset from msg.sender (which is this contract) to c.
        // To make it callable, the test contract must first hold tokens and have allowance; but we cannot mint tokens here.
        // So we perform the supply call in a try/catch to capture whether it reverts.
        bool supplyReverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        uint256 afterSupply = c.balanceOfToken(to);

        // Now attempt redeemToken as the beneficiary 'to' by calling via c from this contract is always msg.sender == address(this).
        // But redeemToken uses msg.sender to adjust imBalances; only the caller's imBalances are affected. So invoking redeemToken here affects this contract's imBalances.
        // We'll call redeemToken and record revert.
        bool redeemReverted;
        uint256 redeemedActual = 0;
        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            redeemReverted = false;
            redeemedActual = mAssetsActual;
        } catch {
            redeemReverted = true;
        }

        // After redeem, observe this contract's underlying balance change via reading balanceOfToken(this)
        uint256 afterRedeem_self = c.balanceOfToken(address(this));

        // General property (single assert):
        // 1) If supply succeeded then the beneficiary's balanceOfToken must be >= before (supply should not decrease beneficiary's reported mAsset balance).
        // 2) If redeem succeeded then the caller's balanceOfToken must not have increased (redeem burns credits from caller, so their reported underlying should not increase); redeem may decrease or keep it.
        // We combine these into one assertion over observed values and revert flags.
        assert((supplyReverted || afterSupply >= before) && (redeemReverted || afterRedeem_self <= before + 1e36));
        // Note: the second conjunct uses a very large bound (before + 1e36) to avoid underflow and to express that redeem cannot arbitrarily inflate caller's reported underlying.
    }

    receive() external payable { }
}

