contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(uint256 mAssetAmount) public payable {
        // No assumptions about mAssetAmount beyond being any uint256
        // Observe public state before the call
        uint256 beforeIm = c.imBalances(address(this));
        uint256 beforeBalanceC = IERC20(c.depositToken()).balanceOf(address(c));
        uint256 beforeBalanceSelf = IERC20(c.depositToken()).balanceOf(address(this));

        bool reverted;
        uint256 mAssetsActual;
        // perform the state-changing call and catch revert
        try c.redeemToken(mAssetAmount) returns (uint256 ret) {
            reverted = false;
            mAssetsActual = ret;
        } catch {
            reverted = true;
            mAssetsActual = 0;
        }

        uint256 afterIm = c.imBalances(address(this));
        uint256 afterBalanceC = IERC20(c.depositToken()).balanceOf(address(c));
        uint256 afterBalanceSelf = IERC20(c.depositToken()).balanceOf(address(this));

        // General rule:
        // If call reverted, public observable state did not change (imBalances and balances unchanged).
        // If it did not revert, then the contract's token balance decreased by mAssetsActual transferred to caller
        // and imBalances decreased by some non-negative amount (creditsBurned) and caller's token balance increased by mAssetsActual.
        // We express this by checking invariants on public getters only.
        assert(
            (reverted && afterIm == beforeIm && afterBalanceC == beforeBalanceC && afterBalanceSelf == beforeBalanceSelf)
            || (!reverted && afterBalanceSelf == beforeBalanceSelf + mAssetsActual && afterBalanceC + mAssetsActual == beforeBalanceC && afterIm <= beforeIm)
        );
    }

    // to allow ERC20 transfers back during redeem
    receive() external payable {}
}

